import sys

def count_ways(n, coins):
    """Count the number of ways to make change for n cents with given coins"""
    coins = sorted(coins)
    dp = [0] * (n + 1)
    dp[0] = 1

    for coin in coins:
        for i in range(coin, n + 1):
            dp[i] += dp[i - coin]

    return dp[n]

def main():
    data = sys.stdin.read().strip().split('\n')
    n = int(data[0])
    coins = list(map(int, data[1].split()))

    result = count_ways(n, coins)
    sys.stdout.write(str(result))

if __name__ == "__main__":
    main()
"}

