S = input().strip()

# Arrays for counts of C, H, E, F
# We scan left to right, maintaining how many of each letter we can still form a new CHEF sequence with
# Actually, we can use a simple four-element list:
counts = [0, 0, 0, 0]  # counts[0] = num Cs available for H, counts[1] = H for E, etc.

for ch in S:
    if ch == 'C':
        counts[0] += 1
    elif ch == 'H':
        counts[1] = min(counts[1] + 1, counts[0])  # H cannot exceed available C
    elif ch == 'E':
        counts[2] = min(counts[2] + 1, counts[1])
    elif ch == 'F':
        counts[3] = min(counts[3] + 1, counts[2])

# The maximum number of complete "CHEF" sequences is the number of completed ones, which is counts[3]
print(counts[3])
"}

