import sys
import math

MOD = 10**9 + 7

def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    return a * b // gcd(a, b)

# Read input
line = sys.stdin.readline().split()
n = int(line[0])
a_list = list(map(int, line[1:1+n]))

# Compute LCM of all a_i
current_lcm = a_list[0]
for i in range(1, n):
    current_lcm = lcm(current_lcm, a_list[i])

# Compute sum of B_i = LCM / A_i
sum_b = 0
for a in a_list:
    sum_b += current_lcm // a

# Output modulo 10^9 + 7
print(sum_b % MOD)
"}

