    s = input().strip()

    # Function to calculate minimum grid area for a given sequence
    def calculate_area(sequence):
        x, y = 0, 0
        min_x, max_x = 0, 0
        min_y, max_y = 0, 0

        for ch in sequence:
            if ch == 'D':
                x += 1
            elif ch == 'S':
                y -= 1
            elif ch == 'A':
                x -= 1
            elif ch == 'W':
                y += 1

            min_x = min(min_x, x)
            max_x = max(max_x, x)
            min_y = min(min_y, y)
            max_y = max(max_y, y)

        return (max_x - min_x + 1) * (max_y - min_y + 1)

    # Try inserting no extra character
    area = calculate_area(s)
    best = area

    # Try inserting each possible character at each position
    for i in range(len(s) + 1):
        for ch in ['W', 'A', 'S', 'D']:
            temp = s[:i] + ch + s[i:]
            area = calculate_area(temp)
            if area < best:
                best = area

    print(best)
