def solve(H, W, N, a):
    """Divide the H x W grid into N disjoint rectangles to maximize the minimum sum of prices."

    We use a dynamic programming approach:
    - We consider all ways to divide the grid into N parts
    - We choose the division that maximizes the minimum sum
    """

    # DP table: dp[n][h][w] = max minimum sum for n rectangles in h x w grid
    dp = [[[0] * (W + 1) for _ in range(H + 1)] for __ in range(N + 1)]

    # Fill DP table
    for n in range(N, 0, -1):
        for h in range(H + 1):
            for w in range(W + 1):
                if n == 1:
                    # One rectangle covers the whole subgrid
                    total = 0
                    for i in range(h, H):
                        for j in range(w, W):
                            total += a[i][j]
                    dp[n][h][w] = total
                else:
                    max_min = 0
                    # Try dividing horizontally
                    for i in range(1, H - h + 1):
                        top_sum = 0
                        for row_idx in range(h, h + i):
                            for col_idx in range(w, W):
                                top_sum += a[row_idx][col_idx]
                        bottom_sum = 0
                        for row_idx in range(h + i, h):
                            for col_idx in range(w, W):
                                bottom_sum += a[row_idx][col_idx]
                        current_min = min(dp[n - 1][h][w + i], dp[1][h + i][w])
                        max_min = max(max_min, current_min)

                    # Try dividing vertically
                    for j in range(1, W - w + 1):
                        left_sum = 0
                        for row_idx in range(h, H):
                            for col_idx in range(w, w + j):
                                left_sum += a[row_idx][col_idx]
                        right_sum = 0
                        for row_idx in range(h, H):
                            for col_idx in range(w + j, w):
                                right_sum += a[row_idx][col_idx]
                        current_min = min(dp[n - 1][h + j][w], dp[1][h][w + j])
                        max_min = max(max_min, current_min)

                    dp[n][h][w] = max_min

    return dp[N][0][0]

# Read input
H, W, N = map(int, input().split())
grid = []
for _ in range(H):
    grid.append(list(map(int, input().split())))

# Solve and print
print(solve(H, W, N, grid))
"}

