# Maximum Hamming distance is L (when each character is in a different position)
# We need to count derangements

# Using the recursive formula for derangements: !n = (n-1) * (!(n-1) + !(n-2))
# Base cases: !1 = 0, !2 = 1

MOD = 1000000007
def derangements(n):
    # Use memoization
    memo = {}

    def _derangements(n):
        if n == 1:
            return 0
        elif n == 2:
            return 1

        if n in memo:
            return memo[n]

        result = ((n - 1) * (_derangements(n - 1) + _derangements(n - 2))) % MOD
        memo[n] = result
        return result

    return _derangements(n)

result = derangements(L)
print(result)
