import sys

def solve() -> None:
    L, R = map(int, sys.stdin.read().split())

    if R - L + 1 > 2019:
        # If there are more than 2019 numbers, we must have a pair with same mod
        min_square = min((i * i) % 2019 for i in range(2019))
        print(min_square)
    else:
        # Check all pairs directly
        min_val = 2019
        for i in range(L, R):
            for j in range(i + 1, R + 1):
                val = (i * j) % 2019
                if val < min_val:
