    p2_x, p2_y = map(int, input().split())

    # Compute cross product for orientation
    cross = (p1_x - p0_x) * (p2_y - p0_y) - (p1_y - p0_y) * (p2_x - p0_x)

    if cross > 0:
        print("COUNTER_CLOCKWISE")
    elif cross < 0:
        print("CLOCKWISE")
    else:
        # Collinear, check if on segment
        if (p2_x - p0_x) * (p1_x - p0_x) > 0:
            print("ONLINE_FRONT")
        elif (p2_x - p0_x) * (p1_x - p0_x) < 0:
            print("ONLINE_BACK")
        else:
            # Check if within y bounds
            if min(p0_y, p1_y) <= p2_y <= max(p0_y, p1_y):
                print("ON_SEGMENT")
            else:
                print("ONLINE_FRONT")  # Should never happen if collinear
