# Keep merging adjacent equal blocks
# We'll do this in O(n) time

# First pass: merge left to right
i = 0
while i < n - 1:
    if a[i] == a[i + 1]:
        a[i] = a[i] + 1
        a[i + 1] = a[i + 1] + 1
        i = 0  # Reset to start from the beginning
    else:
        i += 1

# Second pass: merge left to right
# This might be more efficient
