import sys

def next_permutation(a):
    """Return True if next permutation exists, False otherwise"""
    n = len(a)
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i < 0:
        return False

    j = n - 1
    while a[j] <= a[i]:
        j -= 1

    a[i], a[j] = a[j], a[i]

    k = n - 1
    while k > i and k > j:
        a[i + k - n + 1], a[k] = a[k], a[i + k - n + 1]
        k -= 1

    return True

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    # Maintain current permutation
    a = list(range(1, n + 1))

    # Fenwick Tree for range sum queries (1-indexed)
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, idx, delta):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

        def range_query(self, l, r):
            return self.query(r) - self.query(l - 1)

    ft = FenwickTree(n)
    for i in range(n):
        ft.update(i + 1, a[i])

    for _ in range(q):
        t = int(next(it))
        if t == 1:
            l = int(next(it))
            r = int(next(it))
            res = ft.range_query(l, r)
            print(res)
        else:
            x = int(next(it))
            for _ in range(x):
                if not next_permutation(a):
                    break  # guaranteed not to happen
                # Update Fenwick Tree
                ft.update(a.index(a[-1]), -a[-1])
                ft.update(a.index(a[-2]), -a[-2])
                ft.update(a.index(a[-1]), a[-1])
                ft.update(a.index(a[-2]), a[-2])
                ft.update(a.index(a[-1]), -a[-1])
                ft.update(a.index(a[-2]), -a[-2])
                ft.update(a.index(a[-1]), a[-1])
                ft.update(a.index(a[-2]), a[-2])

solve()
