    """Return True if next permutation exists, False otherwise"""
    n = len(a)
    k = n - 2
    while k >= 0 and a[k] >= a[k + 1]:
        k -= 1
    if k < 0:
        return False

    l = n - 1
    while a[l] <= a[k]:
        l -= 1

    a[k], a[l] = a[l], a[k]

    i, j = k + 1, n - 1
    while i < j:
        a[i], a[j] = a[j], a[i]
        i += 1
        j -= 1

