    N, Q = map(int, input().split())

    # Set to track which positions have white stones
    white_positions = set()

    # Add white stones on bottom side (1, N) to (N, N)
    for row in range(1, N + 1):
        white_positions.add((row, N))

    # Add white stones on right side (N, 1) to (N, N)
    for col in range(1, N + 1):
        white_positions.add((N, col))

    # Process queries
    for _ in range(Q):
        query = input().split()
        typ = int(query[0])
        x = int(query[1])

        # Place white stone at (x, 1) or (1, x)
        if typ == 1:
            white_positions.add((1, x))
            # Go down from (1, x) to (N, x)
            for row in range(1, N + 1):
                # Skip if we've already passed a white stone
                if (row, x) in white_positions:
                    break
                # Only flip black stones
                # Position (row, x) is black if 2 <= row <= N-1 and 2 <= x <= N-1
                if 2 <= row <= N - 1 and 2 <= x <= N - 1 and (row, x) not in white_positions:
                    white_positions.add((row, x))
        else:
            white_positions.add((x, 1))
            # Go right from (x, 1) to (x, N)
            for col in range(1, N + 1):
                # Skip if we've already passed a white stone
                if (x, col) in white_positions:
                    break
                # Only flip black stones
                # Position (x, col) is black if 2 <= x <= N-1 and 2 <= col <= N-1
                if 2 <= x <= N - 1 and 2 <= col <= N - 1 and (x, col) not in white_positions:
                    white_positions.add((x, col))

    # Count remaining black stones
    black_count = 0
    for row in range(2, N):
        for col in range(2, N):
            if (row, col) not in white_positions:
                black_count += 1

    print(black_count)

solve()
