def minimal_cost(t, n):
    # f(n, i, j) = minimal cost to move n disks from rod i to rod j
    # i and j are 1-indexed

    # Base case: n == 1
    if n == 1:
        return t[0][2]  # Move 1 disk from rod 1 to rod 3

    # For n > 1
    def f(i, j, disks):
        """Minimal cost to move disks disks from rod i to rod j"""
        # i, j are 1-indexed
        if i == j:
            return 0

        # Find the rod that is neither i nor j
        if i == 1 and j == 2:
            k = 3
        elif i == 1 and j == 3:
            k = 2
        elif i == 2 and j == 1:
            k = 3
        elif i == 2 and j == 3:
            k = 1
        elif i == 3 and j == 1:
            k = 2
        elif i == 3 and j == 2:
            k = 1

        # Recurrence: move n-1 disks from i to k, move 1 disk from i to j, move n-1 disks from k to j
        cost = f(i, k, disks-1) + t[i-1][j-1] + f(k, j, disks-1)
        return cost

