from math import factorial
from sys import stdin

n = int(stdin.readline())
p = list(map(int, stdin.readline().split()))
q = list(map(int, stdin.readline().split()))

# Helper to calculate ordinal position
def get_ord(perm):
    ord_val = 0
    fact = [1] * n
    for i in range(1, n):
        fact[i] = fact[i-1] * i

    for i in range(n):
        count = 0
        for j in range(i, n):
            if perm[j] < perm[i]:
                count += 1
        ord_val += count * fact[n - i - 1]

    return ord_val

ord_p = get_ord(p)
ord_q = get_ord(q)

target = (ord_p + ord_q) % factorial(n)

# Build the result permutation
result = []
used = [False] * n

for i in range(n):
    for j in range(n):
        if not used[j]:
            # Count how many permutations come before if we choose index j at position i
            count = 0
            for k in range(i, n):
                if perm[k] < perm[j]:
                    count += 1

            if count <= target:
                result.append(j)
                used[j] = True
                target -= count
                break

print(' '.join(map(str, result)))
