def main():
    n = int(input())
    facing = list(map(int, input().split()))

    # cow i: 0 for left, 1 for right
    # cow j sees cow i if:
    # - j < i and facing[j] == 0 (left facing sees left)
    # - j > i and facing[j] == 1 (right facing sees right)

    # When we milk cow i, cows that see cow i lose 1 unit
    # We need to milk cows in an order that minimizes milk loss

    milked = [False] * n
    loss = 0

    # First milk cows facing left (0) in increasing order (from left to right)
    for i in range(n):
        if facing[i] == 0:
            milked[i] = True
            # Check cows that see this cow
            # Cows to the left that are facing right (they see to the right, so see this cow)
            # Cows to the right that are facing left (they see to the left, so see this cow)
            for j in range(i + 1, n):
                if facing[j] == 1 and not milked[j]:
                    loss += 1
            for j in range(i - 1, -1, -1):
                if facing[j] == 0 and not milked[j]:
                    loss += 1

    # Then milk cows facing right (1) in decreasing order (from right to left)
    for i in range(n - 1, -1, -1):
        if facing[i] == 1:
            milked[i] = True
            # Check cows that see this cow
            # Cows to the left that are facing right (they see to the right, so see this cow)
            # Cows to the right that are facing left (they see to the left, so see this cow)
            for j in range(i + 1, n):
                if facing[j] == 1 and not milked[j]:
                    loss += 1
            for j in range(i - 1, -1, -1):
                if facing[j] == 0 and not milked[j]:
                    loss += 1

    print(loss)

if __name__ == "__main__":
    main()
