q = int(input())

# Calculate cross product of vectors (p1-p0) and (p2-p0)
def cross(p0, p1, p2):
    return (p1[0] - p0[0]) * (p2[1] - p0[1]) - (p1[1] - p0[1]) * (p2[0] - p0[0])

for _ in range(q):
    p2 = list(map(int, input().split()))
    val = cross(p0, p1, p2)

    if val > 0:
        print("COUNTER_CLOCKWISE")
    elif val < 0:
        print("CLOCKWISE")
    else:
        # Collinear, check position
        # Check if p2 is on the segment p0-p1
