grid = []
for _ in range(H):
    row = input().strip()
    grid.append(row)

# dp[i][j] = maximum berries from (0,0) to (i,j)
dp = [[0]*W for _ in range(H)]

dp[0][0] = 1 if grid[0][0] == '*' else 0

# Fill first row (can only move right)
for j in range(1, W):
    dp[0][j] = dp[0][j-1] + 1 if grid[0][j] == '*' else dp[0][j-1]

# Fill first column (can only move down)
for i in range(1, H):
    dp[i][0] = dp[i-1][0] + 1 if grid[i][0] == '*' else dp[i-1][0]

# Fill the rest of the grid
for i in range(1, H):
    for j in range(1, W):
        dp[i][j] = dp[i-1][j] + 1 if grid[i][j] == '*' else dp[i-1][j]
        if dp[i-1][j] < dp[i][j-1]:
            dp[i][j] = dp[i][j-1]
        if dp[i][j] < dp[i][j-1] + (1 if grid[i][j] == '*' else 0):
            dp[i][j] = dp[i][j-1] + (1 if grid[i][j] == '*' else 0)

print(dp[H-1][W-1])
