H, W = map(int, input().split())
grid = []
for _ in range(H):
    row = input().strip()
    grid.append(row)

# Greedy path: always choose right or down based on which has more berries in the immediate future
# If both are equal, choose randomly?

path = [(0, 0)]
berries = 0

while path[-1] != (H-1, W-1):
    i, j = path[-1]
    current = grid[i][j]
    if current == '*':
        berries += 1

    right = (i, j+1) if j+1 < W else None
    down = (i+1, j) if i+1 < H else None

    if right is None and down is None:
        break

    if right is None:
        path.append(down)
    elif down is None:
        path.append(right)
    else:
        # Compare berries in the immediate future
        berries_right = 0
        berries_down = 0
        for step in range(3):  # Look ahead 3 steps
            ri, rj = i, j+1+step
            di, dj = i+1+step, j
            if ri < H and rj < W:
                berries_right += 1 if grid[ri][rj] == '*' else 0
            if di < H and dj < W:
                berries_down += 1 if grid[di][dj] == '*' else 0

        if berries_right >= berries_down:
            path.append(right)
        else:
            path.append(down)

print(berries)
