import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    coins = list(map(int, data[1:5]))
    coins = [s for s in coins if s <= n]
    # DP
    dp = [0] * (n + 1)
    dp[0] = 1
    for s in coins:
        for i in range(s, n + 1):
            dp[i] += dp[i - s]
    print(dp[n])

if __name__ == "__main__":
    solve()
