s = input().strip()

# Count all characters
count = {'C': 0, 'H': 0, 'E': 0, 'F': 0}
for char in s:
    if char in count:
        count[char] += 1

# Try to find how many complete "CHEF" we can form sequentially
# Start with 0
result = 0

# Process each character in order
for char in s:
    if char == 'C':
        # Need a 'C' for a new sequence
        count['C'] -= 1
        if count['C'] < 0:
            count['C'] += 1
    elif char == 'H':
        # Need an 'H' for a sequence that already has a 'C'
        count['H'] -= 1
        if count['H'] < 0:
            count['H'] += 1
    elif char == 'E':
        # Need an 'E' for a sequence that has a 'C' and 'H'
        count['E'] -= 1
        if count['E'] < 0:
            count['E'] += 1
    elif char == 'F':
        # Need an 'F' for a sequence that has a 'C', 'H', and 'E'
        count['F'] -= 1
        if count['F'] < 0:
            count['F'] += 1

# After processing all characters, we need to count how many complete sequences
# we have - this should be min of the counts
result = min(count['C'], count['H'], count['E'], count['F'])
print(result)
"}

