def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    max_div = int(n**0.5) + 1
    for i in range(3, max_div, 2):
        if n % i == 0:
            return False
    return True

N = int(input())
trains = []

for _ in range(N):
    h, m, s = map(int, input().split())
    x = 3600 * h + 60 * m + s
    trains.append(x)

# Schedule trains with their halt times
scheduled = []
for i, x in enumerate(trains):
    # Determine halt time
    if is_prime(x):
        halt = 300  # 5 minutes
    elif x % 2 == 1:
        halt = 180  # 3 minutes
    else:
        halt = 120  # 2 minutes

    scheduled.append((x, x + halt))  # (arrival, departure)

# Find minimum number of platforms
# This is equivalent to finding the maximum number of overlapping intervals
scheduled.sort()

platforms = 0
current = 0

for i in range(N):
    arrival, departure = scheduled[i]

    # When a new train arrives, check if any platform is occupied
    if current > 0 and i > 0 and scheduled[i-1][1] > arrival:
        platforms += 1
        current += 1
    else:
        # If there's a platform free, reuse it
        if platforms > 0:
            platforms = min(platforms, current)
            current = max(current, 1)
        else:
            platforms = 1
            current = 1

print(platforms)
