import sys
import math

MOD = 10**9 + 7

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    a_list = list(map(int, data[1:n+1]))

    # Compute LCM of all A_i
    def lcm(a, b):
        return a * b // math.gcd(a, b)

    current_lcm = a_list[0]
    for a in a_list[1:]:
        current_lcm = lcm(current_lcm, a)

    # Compute sum of B_i = current_lcm / A_i
    total = 0
    for a in a_list:
        total += current_lcm // a

    print(total % MOD)

if __name__ == "__main__":
    solve()
"}

