    return True

def solve() -> None:
    q = int(sys.stdin.readline())
    results = []
    for _ in range(q):
        n = int(sys.stdin.readline())
        if n < 4:
            results.append(-1)
            continue
        # Try to use as many 4s as possible
        if n % 4 == 0:
            results.append(n // 4)
        else:
            # Try to use one 6 and the rest 4s
            if (n - 6) % 4 == 0:
                results.append((n - 6) // 4 + 1)
            else:
                # Try to use one 9 and the rest 4s
                # We need at least 4 to make a 9
                if (n - 9) % 4 == 0 and n >= 9:
                    results.append((n - 9) // 4 + 1)
                else:
                    results.append(-1)
    sys.stdout.write("\n".join(map(str, results)))

