        if s[i] == u[j]:
            lcs[i][j] = lcs[i + 1][j + 1] + 1
        else:
            lcs[i][j] = max(lcs[i + 1][j], lcs[i][j + 1])

min_changes = float('inf')

# Try all substrings of s
for start in range(len(s) + 1):
    for end in range(start + 1, len(s) + 1):
        t_len = end - start
        if t_len == 0:
            continue  # Empty string not allowed

        # Get LCS between this substring and u
        lcs_val = lcs[start][0]  # Starting from start of t and start of u

