def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    q = int(next(it))
    queries = []

    for _ in range(q):
        l = int(next(it)) - 1  # 0-indexed
        r = int(next(it)) - 1
        queries.append((l, r))

    # Brute force solution for verification
    def compute_f(arr):
        # Recursive function to compute f
        def f(arr):
            if len(arr) == 1:
                return arr[0]
            else:
                next_arr = [arr[i] ^ arr[i+1] for i in range(len(arr)-1)]
                return f(next_arr)
        return f(arr)

    # Verify and compute maximum f for small queries
    results = []
    for l, r in queries:
        subarray = a[l:r+1]
        max_val = 0
        # Try all subsegments
        for i in range(len(subarray)):
            for j in range(i, len(subarray)):
                subseg = subarray[i:j+1]
                val = compute_f(subseg)
                max_val = max(max_val, val)
        results.append(max_val)

    for result in results:
        print(result)

if __name__ == "__main__":
    solve()
