n, p, w, d = map(int, input().split())

# Edge cases
if p == 0:
    print(0, 0, n)
    exit()

if p > n * w:
    print(-1)
    exit()

# Try all possible number of draws
# But with n up to 10^12, I need to limit the iteration

# Calculate lower and upper bounds for y (draws)
# y >= (p - n*w + w - d - 1) // (w - d) if p < n*w
# y <= p // d

if p < n * w:
    lower_bound = max(0, (p - n*w + w - d - 1) // (w - d))
    upper_bound = min(n, p // d)
    if lower_bound > upper_bound:
        print(-1)
    else:
        for y in range(lower_bound, upper_bound + 1):
            remaining = p - y * d
            if remaining < 0:
                continue
            if remaining % w == 0:
                x = remaining // w
                z = n - x - y
                if x >= 0 and x <= n - y:
                    print(x, y, z)
                    exit()
        print(-1)
else:
    # All wins
    print(n, 0, 0)
"}

