{"code": "import sys

def solve() -> None:
    for line in sys.stdin:
        data = line.strip().split()
        if not data or data[0] == '0' and data[1] == '0' and data[2] == '0':
            break

        H, W, N = int(data[0]), int(data[1]), int(data[2])
        commands = sys.stdin.readline().strip()

        # Read H rows
        maze = []
        for _ in range(H):
            maze.append(sys.stdin.readline().strip())

        # Find entrance and exit
        entrance = None
        exit_pos = None
        for i in range(H):
            for j in range(W):
                if maze[i][j] == 'S':
                    entrance = (i, j)
                elif maze[i][j] == 'G':
                    exit_pos = (i, j)

        # Directions: 0=North, 1=East, 2=South, 3=West
        dir_north, dir_east, dir_south, dir_west = 0, 1, 2, 3
        dir, row, col = dir_north, entrance[0], entrance[1]

        # Execute commands
        for cmd in commands:
            # Turn left or right
            if cmd == 'L':
                dir = (dir - 1) % 4
            elif cmd == 'R':
                dir = (dir + 1) % 4

            # Move forward if possible
            if dir == dir_north and row > 0:
                row -= 1
            elif dir == dir_east and col < W - 1:
                col += 1
            elif dir == dir_south and row < H - 1:
                row += 1
            elif dir == dir_west and col > 0:
                col -= 1

            # Check if reached exit
            if (row, col) == exit_pos:
                print("Yes")
                break
        else:
            # After all commands, check final position
            if (row, col) == exit_pos:
                print("Yes")
            else:
                print("No")

if __name__ == "__main__":
    solve()
"}

