from collections import deque

class Edge:
    def __init__(self, to, rev, cap):
        self.to = to
        self.rev = rev
        self.cap = cap

class MaxFlow:
    def __init__(self, N):
        self.N = N
        self.graph = [[] for _ in range(N)]

    def add_edge(self, fr, to, cap):
        forward = Edge(to, len(self.graph[to]), cap)
        backward = Edge(fr, len(self.graph[fr]), 0)
        self.graph[fr].append(forward)
        self.graph[to].append(backward)

    def bfs_level(self, s, t, level):
        queue = deque()
        level[:] = [0] * self.N
        level[s] = 1
        queue.append(s)
        while queue:
            v = queue.popleft()
            for edge in self.graph[v]:
                if edge.cap > 0 and level[edge.to] == 0:
                    level[edge.to] = level[v] + 1
                    queue.append(edge.to)
                    if edge.to == t:
                        return

    def dfs_flow(self, v, t, upTo, iter_, level):
        if v == t:
            return upTo
        for i in range(iter_[v], len(self.graph[v])):
            edge = self.graph[v][i]
            if edge.cap > 0 and level[v] < level[edge.to]:
                d = self.dfs_flow(edge.to, t, min(upTo, edge.cap), iter_, level)
                if d > 0:
                    edge.cap -= d
                    self.graph[edge.to][edge.rev].cap += d
                    return d
            iter_[v] += 1
        return 0

    def max_flow(self, s, t):
        flow = 0
        level = [0] * self.N
        while True:
            self.bfs_level(s, t, level)
            iter_ = [0] * self.N
            while True:
                f = self.dfs_flow(s, t, float('inf'), iter_, level)
                if f == 0:
                    return flow
                flow += f

def solve():
    W, H = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    # Build flow network
    source = W + H
    sink = W + H + 1
    N = W + H + 2

    mf = MaxFlow(N)
    for col in range(W):
        mf.add_edge(source, col, a[col])
        for row in range(H):
            mf.add_edge(col, row, 1)
    for row in range(H):
        mf.add_edge(row, sink, b[row])

    # Check if all source edges are saturated
    for col in range(W):
        if a[col] > 0 and mf.graph[source][col].cap > 0:
            return 0

    # Check if all sink edges are saturated
    for row in range(H):
        if b[row] > 0 and mf.graph[row][sink].cap > 0:
            return 0

    return 1

solve()
