def solve():
    N, Q = map(int, input().split())

    # Track white stones for each row and each column
    # white_rows_col1: set of rows with white stone in column 1
    # Actually, I need to track for each column, which rows have white stones
    # Let me use a dictionary: column_white_rows[c] = set of rows with white in column c

    column_white_rows = {c: set() for c in range(1, N+1)}
    row_white_cols = {r: set() for r in range(1, N+1)}

    # Set white stones on bottom side (row N, all columns)
    # Set white stones on right side (column N, all rows)
    for c in range(1, N+1):
        column_white_rows[c].add(N)
    for r in range(1, N+1):
        row_white_cols[r].add(N)

    # Process queries
    for _ in range(Q):
        query = input().split()
        if query[0] == '1':  # Place white at (1, x)
            x = int(query[1])
            # Already white? (shouldn't happen per constraints)
            if N not in column_white_rows[x]:
                column_white_rows[x].add(N)
                row_white_cols[N].add(x)

                # Flip down from (1, x)
                r = 2
                while r <= N - 1:
                    # Check if (r, x) is white
                    # (r, x) is white if r is in column_white_rows[x] or x is in row_white_cols[r]
                    if r in column_white_rows[x] or x in row_white_cols[r]:
                        break
                    # Flip (r, x) to white
                    column_white_rows[x].add(r)
                    row_white_cols[r].add(x)
                    r += 1
        else:  # query[0] == '2', Place white at (x, 1)
            x = int(query[1])
            if N not in row_white_cols[x]:
                row_white_cols[x].add(N)
                column_white_rows[N].add(x)

                # Flip right from (x, 1)
                c = 2
                while c <= N - 1:
                    if x in column_white_rows[c] or c in row_white_cols[x]:
                        break
                    column_white_rows[c].add(x)
                    row_white_cols[x].add(c)
                    c += 1

    # Count remaining black stones
    black_count = 0

    for r in range(2, N):
        for c in range(2, N):
            # (r, c) is black if it's not white
            if r not in column_white_rows[c] and c not in row_white_cols[r]:
                black_count += 1

    print(black_count)

solve()
