import sys
from collections import defaultdict

def hex_distance(x1, y1, x2, y2):
    """Calculate distance between two hex blocks."""
    # In a hex grid with offset coordinates:
    # - For odd rows (x odd), distance = |x - x2| + |y - y2|
    # - For even rows (x even), distance = |x - x2| + |y - y2|
    # Let me just use the simple formula for now
    return abs(x1 - x2) + abs(y1 - y2)

def solve():
    while True:
        line = sys.stdin.readline()
        if not line:
            break

        m, n = map(int, line.strip().split())

        if m == 0 and n == 0:
            break

        # Read existing stores
        s = int(sys.stdin.readline().strip())
        stores = []
        for _ in range(s):
            x, y = map(int, sys.stdin.readline().strip().split())
            stores.append((x, y))

        # Read candidate sites
        t = int(sys.stdin.readline().strip())
        best = 0
        for _ in range(t):
            p, q = map(int, sys.stdin.readline().strip().split())

            # Count blocks covered by this candidate site
            count = 0

            # Check all blocks in the grid
            for x in range(1, m + 1):
                for y in range(1, n + 1):
                    min_dist = float('inf')
                    closest_store = None

                    # Check distance to all existing stores
                    for store_x, store_y in stores:
                        dist = hex_distance(x, y, store_x, store_y)
                        if dist < min_dist:
                            min_dist = dist
                            closest_store = store_x, store_y
                        elif dist == min_dist and closest_store != store_x, store_y:
                            # Tied for closest, doesn't count
                            closest_store = None
                            break

                    # If this block is covered by the candidate site
                    # - It has no existing store closest (closest_store is None)
                    # - The candidate is closest (distance <= min_dist and no tie with any store)
                    if closest_store is None:
                        candidate_dist = hex_distance(x, y, p, q)
                        is_covered = True
                        for store_x, store_y in stores:
                            store_dist = hex_distance(x, y, store_x, store_y)
                            if store_dist == candidate_dist and (store_x, store_y) != closest_store:
                                # Tied with an existing store, doesn't count
                                is_covered = False
                                break
                        if is_covered:
                            count += 1

            if count > best:
                best = count

        print(best)

if __name__ == "__main__":
    solve()
