    n = int(lines[0])
    elements = lines[1:n+1]

    positions = {}  # map label to (x, y, z)
    current_pos = (0, 0, 0)

    for e in elements:
        if e in "+x -x +y -y +z -z":
            # Direction symbol, move current position
            dx, dy, dz = 0, 0, 0
            if e == "+x": dx = 1
            elif e == "-x": dx = -1
            elif e == "+y": dy = 1
            elif e == "-y": dy = -1
            elif e == "+z": dz = 1
            elif e == "-z": dz = -1
            current_pos = (current_pos[0]+dx, current_pos[1]+dy, current_pos[2]+dz)
        else:
            # Positive integer, label
            label = int(e)
            # First occurrence defines the position
            if label not in positions:
                positions[label] = current_pos
            else:
                # This label starts a new path from that position
                pass

    return positions


def normalize_points(points):
    """Normalize points by translating to origin"""
    if not points:
        return set()

    # Find the smallest point in each axis
    min_x, min_y, min_z = min(p[0] for p in points), min(p[1] for p in points), min(p[2] for p in points)

    # Translate to origin
    translated = {(x-min_x, y-min_y, z-min_z) for (x, y, z) in points}

    return translated


def rotate_point(p, axis): 
    """Rotate a point 90 degrees around the given axis (x, y, or z)."""
    x, y, z = p
    if axis == 'x':
        return (x, z, -y)
    elif axis == 'y':
        return (z, y, -x)
    elif axis == 'z':
        return (-y, x, z)
    raise ValueError("Invalid rotation axis")


def canonicalize_points(points):
    """Generate canonical form of points by trying all rotations"""
    if not points:
        return frozenset()

    canonical = set()

    # Try all 4 rotations around each axis (identity + 3 rotations per axis)
    for i in range(4):
        rotated = set()
        for p in points:
            rotated_point = p
            for axis in ['x', 'y', 'z']:
                # Apply i rotations around this axis
                for _ in range(i):
                    rotated_point = rotate_point(rotated_point, axis)
            rotated.add(rotated_point)

        # Add canonical form of this rotation
        canonical.add(frozenset(sorted(rotated)))

    # The canonical form is the set of all rotated canonical forms
    return canonical


def are_same(key1, key2):
    """Check if two key descriptions define the same shape"""
    # Get all labeled points for each key
