def solve():
    while True:
        line = sys.stdin.readline().strip()
        if not line:
            break
        H, W, N = map(int, line.split())

        if H == 0 and W == 0 and N == 0:
            break

        commands = sys.stdin.readline().strip()

        maze = []
        start_pos = None
        end_pos = None

        for i in range(H):
            row = sys.stdin.readline().strip()
            maze.append(row)
            for j in range(W):
                if row[j] == 'S':
                    start_pos = (i, j)
                elif row[j] == 'G':
                    end_pos = (i, j)

        if not start_pos or not end_pos:
            print("No")
            continue

        # Directions: 0 = north, 1 = east, 2 = south, 3 = west
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # North, East, South, West

        # Turn: L = left turn, R = right turn
        # L: left turn -> counter-clockwise
        # R: right turn -> clockwise
        # For current direction: L = (dir - 1) % 4, R = (dir + 1) % 4

        i, j = start_pos
        dir = 0  # Start facing north

        # Execute commands
        for cmd in commands:
            if cmd == 'L':
                dir = (dir - 1) % 4
            elif cmd == 'R':
                dir = (dir + 1) % 4

        # Move forward as much as possible
        while True:
            ni = i + directions[dir][0]
            nj = j + directions[dir][1]

            # Check if within bounds and not a wall
            if 0 <= ni < H and 0 <= nj < W and maze[ni][nj] != '#':
                i, j = ni, nj
            else:
                break

        if (i, j) == end_pos:
            print("Yes")
        else:
            print("No")

solve()
