def solve():
    n, p, w, d = map(int, input().split())

    # Brute force over small x values first
    # Try x = 0, 1, 2, ..., min(1000, n)
    for x in range(0, min(1000, n) + 1):
        if x * w > p:
            continue
        if (p - x * w) % d != 0:
            continue
        y = (p - x * w) // d
        z = n - x - y
        if z >= 0:
            # Print this solution
            print(x, y, z)
            return

    # If we didn't find a solution yet, maybe there are no solutions
    print(-1)

