import sys

def recover_string(b):
    # b is the string built from a by concatenating substrings of length 2
    # We need to find the original a
    # If b has length m, then a has length m//2 + 1
    length_a = len(b) // 2 + 1
    a = [0] * length_a

    # a[i] corresponds to b[i*2] for i from 0 to length_a - 1
    for i in range(length_a):
        a[i] = b[i * 2]

    return ''.join(a)

def main():
    t = int(sys.stdin.readline())
    for _ in range(t):
        b = sys.stdin.readline().strip()
        a = recover_string(b)
        print(a)

if __name__ == "__main__":
    main()
"}

