import sys

def solve():
    N = int(sys.stdin.readline())

    # Connect vertex i to (N+1) - i and also to some others
    edges = []

    for i in range(1, N + 1):
        # Connect to the vertex opposite to it
        opposite = N + 1 - i
        if i != opposite:
            edges.append((i, opposite))

    # Add extra edges to make it balanced
    for i in range(1, N + 1):
        if i % 2 == 0:
            edges.append((i, i - 1))
        else:
            edges.append((i, i + 1))

    # Remove duplicate edges and print
    edges = list(set(edges))
    print(len(edges))
    for edge in edges:
        print(edge[0], edge[1])

solve()
