# Try all possible polygon sizes from 3 to n/2
for k in range(3, n // 2 + 1):
    # Check if n is divisible by k (even spacing)
    if n % k != 0:
        continue

    # Spacing between vertices
    spacing = n // k

    # Check all possible start positions
    for start in range(k):
        # Check if all k vertices starting at 'start' with spacing are good
        is_valid = True
        for i in range(k):
