def solve():
    n = int(input())

    # Total sum of numbers from 1 to n
    total_sum = n * (n + 1) // 2

    # Try all possible partitions
    for group1_sum in range(1, total_sum):
        for group2_sum in range(1, total_sum - group1_sum):
            if group1_sum == group2_sum:
                # Found perfect partition
                group1 = []
                sum1 = 0
                for i in range(1, n + 1):
                    if sum1 + i <= group1_sum:
                        group1.append(i)
                        sum1 += i
                    if sum1 == group1_sum:
                        break

