# Calculate number of permutations where Hamming distance is maximum
# This is the number of derangements of L elements

# Base cases
if L == 0:
    print(0)
elif L == 1:
    print(0)
elif L == 2:
    print(1)
else:
    # Calculate using the formula
    n = L
    # Calculate n!
    factorial = 1
    for i in range(1, n + 1):
        factorial *= i

    # Calculate the series part: 1 - 1/1! + 1/2! - 1/3! + ... + (-1)^n / n!
    series = 0.0
    for i in range(n + 1):
        if i == 0:
            term = 1.0
        else:
            term = (-1) ** i / (1)
            for j in range(1, i + 1):
                term /= j
        series += term

    # Multiply by n! and take modulo
    result = int(factorial * series)
    print(result % 1000000007)
