# If we don't have at least 3 good knights, return NO
if good_knights < 3:
    print("NO")
else:
    # Try each possible number of vertices for the polygon
    for k in range(3, n + 1):
        # Check if a regular polygon with k vertices is possible
        if n % k == 0:
            s = n // k  # Step size between vertices

            # Try all possible starting positions
            found = False
            for start in range(n):
                # Check if all k positions are good knights
                all_good = True
                for i in range(k):
                    if moods[(start + i * s) % n] != 1:
                        all_good = False
                        break
                if all_good:
                    found = True
                    break

            if found:
                print("YES")
                break
    else:
        print("NO")
